// SLATE-FILECHECK-DEFINES DEFAULT

int
main(int na, char* argv[])
{
	int wflg = 0, tflg = 0;
	int dflg = 0;
	__builtin_exit(0);
	while(1)
	{
		switch(argv[1][0])
		{
			help:
				__builtin_exit(0);
			case 'w':
			case 'W':
				wflg = 1;
				break;
			case 't':
			case 'T':
				tflg = 1;
				break;
			case 'd':
				dflg = 1;
				break;
		}
	}
}

